export const ORDER_STATES = ["placed", "paid", "packed", "shipped", "delivered"] as const;

export type OrderState = (typeof ORDER_STATES)[number];

export function isOrderState(value: unknown): value is OrderState {
  return typeof value === "string" && (ORDER_STATES as readonly string[]).includes(value);
}

export function nextState(state: OrderState): OrderState | undefined {
  return ORDER_STATES[ORDER_STATES.indexOf(state) + 1];
}

export function canCancelFrom(state: OrderState): boolean {
  return ORDER_STATES.indexOf(state) < ORDER_STATES.indexOf("shipped");
}

